<script lang="ts">
 import { invalidateAll } from '$app/navigation';let {model,t}:{model:Record<string,any[]>;t:(key:string)=>string}=$props();let message=$state(''),busy=$state(false);
 async function upload(event:SubmitEvent){event.preventDefault();busy=true;try{const form=event.currentTarget as HTMLFormElement;const data=new FormData(form);for(const key of ['lot_id','vineyard_id'])if(!data.get(key))data.delete(key);const res=await fetch('/api/assets',{method:'POST',body:data});const result=await res.json();message=res.ok?t('saved'):result.message;if(res.ok){form.reset();await invalidateAll();}}finally{busy=false;}}
</script>
<div class="card"><h2>{t('assets')}</h2><ul>{#each model.assets as asset}<li><a href={'/api/assets/'+asset.id}>{asset.filename}</a></li>{/each}</ul><form onsubmit={upload}><label class="file">{t('upload')}<input name="file" type="file" required accept="image/png,image/jpeg,application/pdf" /></label><label>{t('lot_id')}<select name="lot_id"><option value="">—</option>{#each model.lots as lot}<option value={lot.id}>{lot.code} · {lot.name}</option>{/each}</select></label><label>{t('vineyard_id')}<select name="vineyard_id"><option value="">—</option>{#each model.vineyards as vineyard}<option value={vineyard.id}>{vineyard.name}</option>{/each}</select></label><button disabled={busy}>{t('save')}</button></form><p role="status">{message}</p></div>
<style>.file{grid-column:1/-1}form{display:grid;gap:15px;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));align-items:end}ul{padding-left:18px;line-height:2}</style>
